1	package retention
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sync"
11		"syscall"
12	)
13	
14	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
15	const (
16		stateFileName = "retention-state.json"
17		lockFileName  = ".retention.lock"
18	)
19	
20	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
21	//
22	// 同一个目录可以被本机上的多个程序（进程）同时打开：
23	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
24	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
25	type Store struct {
26		dir string
27	
28		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
29		opMu sync.RWMutex
30	}
31	
32	// Open 打开（或创建）一个本地保存位置。
33	// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
34	// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
35	// 还拼接了其他内容等）时返回 ErrCorruptState，不会返回可继续办理的保管库，
36	// 已有记录保持原样，不会被清空、修补或覆盖。
37	func Open(dir string) (*Store, error) {
38		if dir == "" {
39			return nil, errors.New("retention: 保存位置不能为空")
40		}
41		if err := os.MkdirAll(dir, 0o755); err != nil {
42			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
43		}
44		s := &Store{dir: dir}
45		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
46		if _, err := s.load(); err != nil {
47			return nil, err
48		}
49		return s, nil
50	}
51	
52	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
53	func (s *Store) Close() error { return nil }
54	
55	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
56	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
57	
58	// lock 取得跨进程排他锁，返回解锁函数。
59	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
60	func (s *Store) lock() (func(), error) {
61		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
62		if err != nil {
63			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
64		}
65		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
66			f.Close()
67			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
68		}
69		return func() {
70			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
71			_ = f.Close()
72		}, nil
73	}
74	
75	// rlock 取得跨进程共享锁，用于只读核对。
76	func (s *Store) rlock() (func(), error) {
77		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
78		if err != nil {
79			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
80		}
81		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
82			f.Close()
83			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
84		}
85		return func() {
86			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
87			_ = f.Close()
88		}, nil
89	}
90	
91	// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
92	//
93	// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
94	// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
95	// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
96	// 绝不只使用前一段内容，也不会改动原文件。
97	func (s *Store) load() (*storeData, error) {
98		raw, err := os.ReadFile(s.statePath())
99		if err != nil {
100			if errors.Is(err, os.ErrNotExist) {
101				return newStoreData(), nil
102			}
103			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
104		}
105		trimmed := bytes.TrimSpace(raw)
106		if len(trimmed) == 0 {
107			return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
108		}
109		// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
110		if string(trimmed) == "null" {
111			return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
112		}
113		data := newStoreData()
114		// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
115		// 合法对象后面再拼接任何内容都会在这里报错。
116		if err := json.Unmarshal(raw, data); err != nil {
117			return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
118		}
119		if data.Archives == nil {
120			data.Archives = map[string]*archiveRecord{}
121		}
122		if data.Manifests == nil {
123			data.Manifests = map[string]*manifestRecord{}
124		}
125		// 兼容引入修订功能之前保存的保管库：没有记录最初截止日时，
126		// 登记截止日就是最初截止日。
127		for _, ar := range data.Archives {
128			if ar.InitialEnd.IsZero() {
129				ar.InitialEnd = ar.End
130			}
131		}
132		return data, nil
133	}
134	
135	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
136	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
137	func (s *Store) save(data *storeData) error {
138		buf, err := json.MarshalIndent(data, "", "  ")
139		if err != nil {
140			return fmt.Errorf("retention: 状态编码失败: %w", err)
141		}
142		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
143		if err != nil {
144			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
145		}
146		tmpName := tmp.Name()
147		cleanup := func() { _ = os.Remove(tmpName) }
148		if _, err := tmp.Write(buf); err != nil {
149			tmp.Close()
150			cleanup()
151			return fmt.Errorf("retention: 写入状态失败: %w", err)
152		}
153		if err := tmp.Sync(); err != nil {
154			tmp.Close()
155			cleanup()
156			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
157		}
158		if err := tmp.Close(); err != nil {
159			cleanup()
160			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
161		}
162		if err := os.Rename(tmpName, s.statePath()); err != nil {
163			cleanup()
164			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
165		}
166		// 刷目录，确保 rename 在崩溃后仍然落盘。
167		if dir, err := os.Open(s.dir); err == nil {
168			_ = dir.Sync()
169			_ = dir.Close()
170		}
171		return nil
172	}
173	
174	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
175	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
176	func (s *Store) mutate(fn func(*storeData) error) error {
177		s.opMu.Lock()
178		defer s.opMu.Unlock()
179		unlock, err := s.lock()
180		if err != nil {
181			return err
182		}
183		defer unlock()
184		data, err := s.load()
185		if err != nil {
186			return err
187		}
188		if err := fn(data); err != nil {
189			return err
190		}
191		return s.save(data)
192	}
193	
194	// view 在共享锁内重读状态并执行只读查询。
195	func (s *Store) view(fn func(*storeData) error) error {
196		s.opMu.RLock()
197		defer s.opMu.RUnlock()
198		unlock, err := s.rlock()
199		if err != nil {
200			return err
201		}
202		defer unlock()
203		data, err := s.load()
204		if err != nil {
205			return err
206		}
207		return fn(data)
208	}
209

