	if _, err := s.Destroy(DestructionRequest{
		ApplicationID: "APP-0", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-2"},
	}); err != nil {
		t.Fatal(err)
	}

	original := readStateFile(t, dir)
	// 已销毁档案 A-2 上补一条解除信息不完整的冻结；A-1 保持正常。
